import os
import subprocess

def validate_document_fields(payload, config=None):
    config = config or {}
    result = {}
    for field_name, field_config in config.items():
        min_confidence = field_config.get("min_confidence")
        extracted_field = payload.get(field_name)
        detected_confidence = payload.get(f"{field_name}_confidence")

        if extracted_field is None:
            raise ValueError(f"Field '{field_name}' is missing in the document extraction result.")

        if detected_confidence is None:
            raise ValueError(f"Confidence score for field '{field_name}' is missing in the document extraction result.")

        if min_confidence is not None and detected_confidence < min_confidence:
            raise ValueError(f"Confidence score {detected_confidence} for field '{field_name}' is below the required minimum of {min_confidence}.")

    result["valid"] = True
    result["fields"] = payload
    return result
